43:     fun debris(index: Int, age: Double, size: Float, sourceLifetime: Double): SoftDebrisEnvelope {
44:         val tier = Math.floorMod(index, 3)
45:         val x = when (tier) { 0 -> 0.18; 1 -> 0.32; else -> 0.50 }
46:         val y = when (tier) { 0 -> 0.065; 1 -> 0.11; else -> 0.16 }
47:         val speed = when (tier) { 0 -> 1.55; 1 -> 1.05; else -> 0.65 }
48:         val lifetime = minOf(sourceLifetime, when (tier) { 0 -> 0.135; 1 -> 0.190; else -> 0.250 })
49:         // Eight unequal fragments read as dry flakes; four overlapping puff nodes stay disabled.
50:         val peak = if (index == 3 || index == 7 || index == 8 || index == 9) 0.0
51:             else when (tier) { 0 -> 0.60; 1 -> 0.45; else -> 0.32 }
52:         val delay = when (tier) { 0 -> 0.004; 1 -> 0.012; else -> 0.020 } + (index.coerceAtLeast(0) / 3) * 0.002
53:         val gain = size.toDouble()
54:         val opacity = if (!age.isFinite() || age < delay || age >= lifetime || lifetime <= 0.0) 0f else {
55:             val enter = ((age - delay) / 0.012).coerceIn(0.0, 1.0)
56:             val smoothEnter = enter * enter * (3.0 - 2.0 * enter)
57:             (peak * smoothEnter * (1.0 - (age / lifetime).pow(1.5))).coerceIn(0.0, 1.0).toFloat()
58:         }
59:         return SoftDebrisEnvelope(Vector3(x * gain, y * gain, gain), speed, lifetime, opacity)
60:     }
